package io.github.miklires.mevents.event;
import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.inventory.InventoryMoveItemEvent;import org.bukkit.event.player.PlayerInteractEvent;
public final class EventListener implements Listener{private final EventService service;public EventListener(EventService service){this.service=service;}@EventHandler(ignoreCancelled=true)public void interact(PlayerInteractEvent event){if(event.getClickedBlock()!=null&&service.claimDrop(event.getPlayer(),event.getClickedBlock().getLocation()))event.setCancelled(true);}@EventHandler(ignoreCancelled=true)public void breakBlock(BlockBreakEvent event){if(service.protects(event.getBlock().getLocation()))event.setCancelled(true);}@EventHandler(ignoreCancelled=true)public void explode(BlockExplodeEvent event){event.blockList().removeIf(block->service.protects(block.getLocation()));}@EventHandler(ignoreCancelled=true)public void entityExplode(EntityExplodeEvent event){event.blockList().removeIf(block->service.protects(block.getLocation()));}@EventHandler(ignoreCancelled=true)public void move(InventoryMoveItemEvent event){var source=event.getSource().getLocation();var destination=event.getDestination().getLocation();if(source!=null&&service.protects(source)||destination!=null&&service.protects(destination))event.setCancelled(true);}@EventHandler(ignoreCancelled=true)public void damage(EntityDamageByEntityEvent event){Player player=EventService.playerAttacker(event);if(player!=null)service.recordDamage(event.getEntity().getUniqueId(),player,event.getFinalDamage());}@EventHandler public void death(EntityDeathEvent event){service.bossDied(event.getEntity().getUniqueId());}}
